head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/

scwin.vScrenID = "ULDFIS00400_02.xml";
///////// 1. 변수 및 선언 영역 /////////
scwin.vKisCd = ""; // 조회조건 기업코드
scwin.vAcntclsDt = ""; // 조회조건 결산일자

/**
 *  화면이 최초 로드될때 실행되는 초기화 이벤트
 *  (초기 데이터 조회나 컴포넌트 설정) 
 */

///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {
    scwin.init();
};

/**
 *  현재 로딩된 페이지가 초기화되거나 종료될때(다른 화면으로 이동하거나 페이지를 닫기전) 발생하는 이벤트
 *  (주로 SPA(Single Page Application) 환경에서 전역 자원을 해제하거나 메모리 누수 방지)
 */
scwin.onpageunload = function() {

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 *  화면 초기화
 */
scwin.init = function() {
    // 결산일자 조회
    $p.parent().frame_head.getWindow().scwin.fn_SrchAcntclsDt();
    scwin.search();
};

/**
 *  데이터셋 초기화.
 */
scwin.initDs = function() {
    dlt_consNotesSubsListRes.setData([]);
};

/**
 *  조회조건 유효성 체크
 */
scwin.chkValid = function() {

    // 필수항목 체크
    vKisCd = $p.parent().frame_head.getWindow().scwin.fn_GetKisCd();
    vAcntclsDt = $p.parent().frame_head.getWindow().scwin.fn_GetAcntclsDt();

    if (vKisCd === "" || vAcntclsDt === "") {
        return false;
    }

    return true;

};

/**
 * 연결대상종속회사 조회
 */
scwin.search = async function() {

    //데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크
    if (!scwin.chkValid()) {
        return;
    }

    dma_consNotesSubsInfoReq.set("kisCd", vKisCd);
    dma_consNotesSubsInfoReq.set("acntclsDt", vAcntclsDt);
    const sbmOptions = {
        id : "sbm_consNotesSubs",
        action : "/api/listing/nice/financial/cons-notes/subs",
        method : "get",
        ref : "dma_consNotesSubsInfoReq",
        target : "dlt_consNotesSubsListRes|append",
        gridview : "grd_ConnObjDpndCom",
        isProcessMsg : false
    };
    const res = await await $c.sbm.executeDynamic(sbmOptions);
    dlt_consNotesSubsListRes.setJSON(res.responseJSON.body);

};

/**
 *  엑셀파일다운로드
 */
scwin.excelDownload = function() {

    if (dlt_consNotesSubsListRes.getRowCount() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }

    const options = {
        fileName : "연결대상종속회사" 
    };

    const infoArray = {};
    $c.data.downloadGridViewExcel(grd_ConnObjDpndCom, options, infoArray);

};

/**
 *  그리드 연결구분 항목 커서 위치시 설명 표시
 */
scwin.grd_ConnObjDpndCom_tooltipFormatter = function (rowIndex, colIndex, label, isOverflow, type) {

    if (grd_ConnObjDpndCom.getColumnID(colIndex) === "connRsnCd") {
        return $c.stf.getConnRsnCdNm1(dlt_consNotesSubsListRes.getCellData(rowIndex, "connRsnCd"));
    }

};
